import { defineComponent, getCurrentInstance, h } from "vue";
import type { Component } from "vue";

/**
 * Wraps a generated Stencil Vue proxy so `v-model.lazy` is honoured.
 *
 * The proxies generated by @stencil/vue-output-target always update the
 * `v-model` binding on the configured model event (`ionInput` for the input
 * components). Vue passes `v-model.lazy` through as a `modelModifiers`
 * prop (`{ lazy: true }`), which the generated proxy never reads, so the
 * bound value updates on every keystroke even with `.lazy`.
 *
 * The wrapper keeps the default behaviour (update on the inner proxy's
 * `update:modelValue`, which fires on `ionInput`) and only changes it when
 * `.lazy` is present: then it drops those updates and commits the value on
 * `ionChange` instead, which fires at the same moments as a native `change`
 * event. The user's own `ionChange` listener, if any, is still called.
 *
 * `modelValue` is only forwarded to the inner proxy when the parent actually
 * provided it (checked via the vnode props, so `v-model` bound to
 * `undefined` still clears the input). Otherwise the inner proxy falls back
 * to the `value` prop, exactly as it does without the wrapper, so
 * `:value="..."` without `v-model` keeps working.
 */
export function withLazyModel<T extends Component>(
  component: T,
  commitEvent = "ionChange"
) {
  const commitHandlerKey = `on${commitEvent[0].toUpperCase()}${commitEvent.slice(
    1
  )}`;

  return defineComponent({
    name: (component as unknown as { name?: string }).name,
    props: {
      modelValue: {
        type: [String, Number, Boolean, Object, Array],
        default: undefined,
      },
      modelModifiers: {
        type: Object,
        default: () => ({}),
      },
    },
    emits: ["update:modelValue"],
    setup(props, { attrs, slots, emit }) {
      const isLazy = () =>
        Boolean(
          (props.modelModifiers as Record<string, boolean> | undefined)?.lazy
        );

      return () => {
        const instance = getCurrentInstance();
        const hasModelValue =
          instance?.vnode.props != null && "modelValue" in instance.vnode.props;
        const userCommitHandler = (attrs as Record<string, unknown>)[
          commitHandlerKey
        ] as ((e: CustomEvent) => void) | undefined;

        return h(
          component as never,
          {
            ...attrs,
            ...(hasModelValue ? { modelValue: props.modelValue } : {}),
            "onUpdate:modelValue": (value: unknown) => {
              if (!isLazy()) {
                emit("update:modelValue", value);
              }
            },
            [commitHandlerKey]: (e: CustomEvent) => {
              if (typeof userCommitHandler === "function") {
                userCommitHandler(e);
              }
              if (isLazy()) {
                emit(
                  "update:modelValue",
                  (e.target as { value?: unknown } | null)?.value
                );
              }
            },
          },
          slots
        );
      };
    },
  });
}
